{"code":"def transform(grid):
 h=len(grid); w=len(grid[0]); pts=[]
 for r,row in enumerate(grid):
  for v in row:
   if v: pts.append((r,v)); break
 pts.sort(); first=pts[0][1]; out=[[0]*w for _ in range(h)]
 for r in range(h):
  if r==0: c=first; out[r]=[c]*w; continue
  if any(r==q for q,c in pts): c=next(c for q,c in pts if q==r); out[r]=[c]*w; continue
  if r==h-1: c=pts[-1][1]
  else:
   q,c=min(pts, key=lambda x:(abs(x[0]-r), x[0]))
   c=c
  out[r][0]=out[r][-1]=c
 return out"}

